    'definition_performance_period' => '"Performance Period" refers to the duration over which the Employee\'s performance will be assessed, typically on a quarterly or annual basis.',

    'employment_agreement_title' => 'EMPLOYMENT AGREEMENT',
    'employment_agreement_intro' => 'This Employment Agreement ("Agreement") is made and entered into on this {date}, by and between {company_name} (hereinafter referred to as "the Company"), and {employee_name} (hereinafter referred to as "the Employee").',
    'employee_hired_as_full' => 'The Employee is hereby employed by the Company in the position of {position}. The Employee shall perform such duties as are customarily associated with this position and such other duties as the Company may from time to time assign, commensurate with the Employee\'s skills and abilities. These duties are outlined in more detail in the job description provided to the Employee, which is incorporated by reference herein.',
    'employee_report_to' => 'The Employee shall report directly to [Supervisor\'s Name/Title] or such other person as the Company may designate.',
    'at_will_employment_full' => 'The Employee\'s employment with the Company is "at-will." This means that either the Employee or the Company may terminate the employment relationship at any time, with or without cause, and with or without notice, subject to applicable law.',
    'probationary_period' => 'The Employee\'s employment shall commence with a probationary period of [Number] months, during which the Company will assess the Employee\'s suitability for the role. The Company reserves the right to extend or terminate the probationary period at its discretion.',
    'base_salary_details' => 'The Employee shall receive a base salary of [Amount] per [Period, e.g., month, annum], payable in accordance with the Company\'s standard payroll practices, subject to all applicable taxes and deductions.',
    'benefits_details' => 'The Employee shall be eligible to participate in the Company\'s employee benefits programs, including health insurance, paid time off, and retirement plans, as per Company policy and eligibility requirements.',
    'expense_reimbursement' => 'The Company shall reimburse the Employee for all reasonable and necessary business expenses incurred in the performance of the Employee\'s duties, upon submission of proper documentation and in accordance with Company policy.',
    'duties_responsibilities' => 'Duties and Responsibilities',
    'employee_responsibilities_list' => 'The Employee agrees to perform the following responsibilities:',
    'perform_assigned_tasks' => 'Perform all duties and tasks assigned by the Company diligently and competently.',
    'maintain_professionalism' => 'Maintain a high level of professionalism, integrity, and ethical conduct at all times.',
    'adapt_to_changing_duties' => 'The Employee acknowledges that the Company may modify job duties and responsibilities as business needs evolve.',
    'working_hours' => 'Working Hours',
    'standard_working_hours' => 'The Employee\'s standard working hours shall be [Number] hours per week, from [Start Day] to [End Day], from [Start Time] to [End Time].',
    'overtime_policy' => 'Any work performed beyond standard working hours must be approved in advance and will be compensated according to applicable labor laws and Company policy.',
    'employee_confidentiality_agree_full' => 'The Employee acknowledges that during the course of employment, they will have access to and be entrusted with Confidential Information belonging to the Company and its clients. The Employee agrees to keep all such information strictly confidential.',
    'non_disclosure_details' => 'The Employee agrees not to disclose, publish, or utilize any Confidential Information for any purpose other than the performance of duties for the Company, either during or after the term of employment.',
    'termination' => 'Termination',
    'termination_at_will' => 'This Agreement may be terminated by either party at any time, with or without cause, and with or without notice, subject to any applicable legal requirements.',
    'termination_with_cause' => 'The Company may terminate this Agreement immediately for cause, including but not limited to gross misconduct, insubordination, violation of company policies, or breach of this Agreement.',
    'return_of_property' => 'Upon termination of employment, the Employee agrees to immediately return to the Company all Company property, including but not limited to documents, equipment, and any materials containing Confidential Information.',

    'confidentiality_agreement_title' => 'CONFIDENTIALITY AND NON-DISCLOSURE AGREEMENT',
    'confidentiality_agreement_intro' => 'This Confidentiality and Non-Disclosure Agreement ("Agreement") is made and entered into on this {date}, by and between {company_name} (hereinafter referred to as "the Disclosing Party"), and {employee_name} (hereinafter referred to as "the Receiving Party").',
    'employee_agrees_confidential_full' => 'The Receiving Party acknowledges that during the course of their engagement with the Disclosing Party, they may be exposed to highly sensitive and proprietary information. The Receiving Party agrees to maintain the strictest confidence regarding all Confidential Information.',
    'employee_not_disclose_full' => 'The Receiving Party shall not, directly or indirectly, disclose, disseminate, publish, or use any Confidential Information for any purpose other than the authorized purpose as defined in this Agreement, without the prior written consent of the Disclosing Party.',
    'return_of_confidential_info' => 'Upon the request of the Disclosing Party, or upon termination of the engagement, the Receiving Party shall immediately return all Confidential Information, including all copies thereof, or destroy such information as directed by the Disclosing Party.',
    'exclusions' => 'Exclusions',
    'exclusions_clause' => 'The obligations of confidentiality under this Agreement shall not apply to information that: (a) is or becomes publicly available without breach of this Agreement; (b) was known to the Receiving Party prior to disclosure by the Disclosing Party; (c) is independently developed by the Receiving Party without use of Confidential Information; or (d) is required to be disclosed by law or court order.',
    'confidentiality_duration_employment_full' => 'The obligations of confidentiality and non-disclosure set forth herein shall remain in full force and effect during the term of engagement between the parties.',
    'confidentiality_duration_post_employment_full' => 'Notwithstanding the termination of engagement, the obligations related to Confidential Information shall survive and continue for a period of {years} ({{years}}) years from the date of termination.',
    'remedies' => 'Remedies',
    'remedies_clause' => 'The Receiving Party acknowledges that any breach of this Agreement would cause irreparable harm to the Disclosing Party, for which monetary damages would be inadequate. Therefore, the Disclosing Party shall be entitled to seek injunctive relief in addition to any other remedies available at law or in equity.',

    'performance_agreement_title' => 'EMPLOYEE PERFORMANCE AGREEMENT',
    'performance_agreement_intro' => 'This Employee Performance Agreement ("Agreement") is entered into on this {date}, by and between {company_name} (hereinafter referred to as "the Company"), and {employee_name} (hereinafter referred to as "the Employee"). This Agreement outlines the performance expectations and goals for the Employee for the upcoming Performance Period.',
    'employee_evaluated_kpis_full' => 'The Employee\'s performance will be evaluated based on the following Key Performance Indicators (KPIs):',
    'quality_of_work_desc' => '**Quality of Work**: Accuracy, completeness, and effectiveness of tasks performed.',
    'productivity_desc' => '**Productivity**: Efficiency in completing assigned tasks within deadlines.',
    'adherence_to_policies_desc' => '**Adherence to Company Policies**: Compliance with all company policies, procedures, and safety regulations.',
    'teamwork_collaboration_desc' => '**Teamwork and Collaboration**: Effectiveness in working with colleagues and contributing to team goals.',
    'specific_goals_targets' => 'In addition to the general KPIs, the Employee will work towards specific goals and targets as mutually agreed upon with their direct supervisor, to be reviewed periodically.',
    'responsibilities_support' => 'Responsibilities and Support',
    'employee_responsibilities_performance' => 'The Employee is responsible for actively working towards achieving the outlined performance objectives and seeking clarification or support when needed.',
    'company_support' => 'The Company commits to providing necessary resources, training, and feedback to support the Employee in achieving their performance goals.',
    'performance_reviewed_quarterly_full' => 'Performance will be formally reviewed on a [e.g., quarterly, semi-annual] basis. These reviews will include a discussion of achievements, areas for improvement, and objective setting for the next period.',
    'continuous_feedback_full' => 'In addition to formal reviews, continuous feedback and coaching will be provided to the Employee to support ongoing development and performance improvement.',
    'consequences_performance' => 'Consequences of Performance',
    'satisfactory_performance' => '**Satisfactory Performance**: Achievement of performance objectives may lead to opportunities for growth, bonuses, or salary adjustments in accordance with company policy.',
    'unsatisfactory_performance' => '**Unsatisfactory Performance**: Failure to meet performance objectives may result in a Performance Improvement Plan (PIP), re-evaluation of employment, or disciplinary action, up to and including termination of employment.',

